def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min((v for v in counts if v != max(counts, key=counts.get)),
                 key=lambda v: counts[v])
    background = max(counts, key=counts.get)

    points = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == marker}
    # Keep the connected marker object as the template.
    start = next(iter(points))
    obj = {start}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if (nr, nc) in points and (nr, nc) not in obj:
                obj.add((nr, nc))
                q.append((nr, nc))

    out = [row[:] for row in grid]
    for dr in range(-h, h):
        for dc in range(-w, w):
            if dr == 0 and dc == 0:
                continue
            dest = [(r + dr, c + dc) for r, c in obj]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == background
                   for r, c in dest):
                for r, c in dest:
                    out[r][c] = marker
    return out
